return {["fb220_01"]={["down"]=[[fb220_03]],["dsc"]=[[这里是一间宽敞的石厅。石厅里放着各种石制物件，石桌、石椅应有尽有，摆放得整整齐齐，但由于物件的年代太过久远，通通散发出一股腐烂难闻的味道。]],["enterfb203_ble"]=1,["id"]=[[fb220_01]],["name"]=[[石厅]],["role1"]=[[dgnpc01a]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb220_36]],["visible"]=1},["fb220_02"]={["down"]=[[fb220_05]],["dsc"]=[[这里是一间陈旧的棺室。棺室四周肃穆无声，不知何处的光源将棺室微微照亮，只见一个厚重的棺材静静地放在棺室中央，让人心中隐隐不安。]],["enterfb203_ble"]=1,["id"]=[[fb220_02]],["item1"]=[[dgwp11a]],["item2"]=[[dgwp04c]],["name"]=[[棺室]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=0},["fb220_03"]={["down"]=[[fb220_08]],["dsc"]=[[这里是一条狭窄的墓道。墓道两旁尽是石壁，石壁上镶着颗颗鹅蛋大小的明珠，暗透微光，只能将墓道照亮数米。墓道前方幽暗深邃，不知通向何处。]],["enterfb203_ble"]=1,["id"]=[[fb220_03]],["name"]=[[墓道]],["right"]=[[fb220_04]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb220_01]],["visible"]=1},["fb220_04"]={["dsc"]=[[这里是一个窄小的石洞。石洞似是天然形成的，顶上倒挂着许多钟乳石笋，石笋尖锐，时不时有水滴从石笋尖滴落，在凹凸不平的地面上积起了许多水洼。]],["enterfb203_ble"]=1,["id"]=[[fb220_04]],["item1"]=[[trigger02]],["item2"]=[[dgwp02c]],["left"]=[[fb220_03]],["name"]=[[小石洞]],["right"]=[[fb220_05]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb220_05"]={["dsc"]=[[这里是一座墓穴，墓穴中央散乱摆放着几具棺材，其中只有一具棺材的棺板合上了，其他打开的棺材中好像空空如也。墓穴的地面和内壁上有道道划痕，让人毛骨悚然。]],["enterfb203_ble"]=1,["id"]=[[fb220_05]],["item1"]=[[dgwp04a]],["item2"]=[[trigger01]],["left"]=[[fb220_04]],["name"]=[[机关墓穴]],["right"]=[[fb220_06]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb220_02]],["visible"]=1},["fb220_06"]={["down"]=[[fb220_10]],["dsc"]=[[这里是一个阴冷的墓洞。墓洞是人为开凿而成的，墓洞中散落了不少骸骨和机关残骸，让人触目惊心，而墓洞后方的出口不知通往何处。]],["enterfb203_ble"]=1,["id"]=[[fb220_06]],["left"]=[[fb220_05]],["name"]=[[墓洞]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=0},["fb220_07"]={["dsc"]=[[这里是一间简陋的石室。石室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。看来很久以前有人在这里住过。]],["enterfb203_ble"]=1,["id"]=[[fb220_07]],["item1"]=[[dgwp03a]],["name"]=[[石室]],["right"]=[[fb220_08]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb220_08"]={["down"]=[[fb220_11]],["dsc"]=[[这里是一条狭窄的墓道。墓道两旁尽是石壁，石壁上镶着颗颗鹅蛋大小的明珠，暗透微光，只能将墓道照亮数米。墓道前方幽暗深邃，不知通向何处。]],["enterfb203_ble"]=1,["id"]=[[fb220_08]],["left"]=[[fb220_07]],["name"]=[[墓道]],["right"]=[[fb220_09]],["role1"]=[[dgnpc03]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb220_03]],["visible"]=1},["fb220_09"]={["dsc"]=[[这里是一间简陋的石室。石室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。看来很久以前有人在这里住过。]],["enterfb203_ble"]=1,["id"]=[[fb220_09]],["item1"]=[[dgwp03b]],["left"]=[[fb220_08]],["name"]=[[石室]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb220_10"]={["down"]=[[fb220_14]],["dsc"]=[[这里是一间陈旧的棺室。棺室四周肃穆无声，不知何处的光源将棺室微微照亮，只见一个厚重的棺材静静地放在棺室中央，让人心中隐隐不安。]],["enterfb203_ble"]=1,["id"]=[[fb220_10]],["item1"]=[[dgwp04d]],["name"]=[[棺室]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb220_06]],["visible"]=1},["fb220_11"]={["down"]=[[fb220_19]],["dsc"]=[[这里是一条狭窄的墓道。墓道两旁尽是石壁，石壁上镶着颗颗鹅蛋大小的明珠，暗透微光，只能将墓道照亮数米。墓道前方幽暗深邃，不知通向何处。]],["enterfb203_ble"]=1,["id"]=[[fb220_11]],["name"]=[[墓道]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb220_08]],["visible"]=1},["fb220_12"]={["down"]=[[fb220_20]],["dsc"]=[[这里是一所宽敞的祭厅。一个拳头大小的明珠挂在祭厅上方，将整个祭厅照得明亮。祭厅四周皆是石壁，地面上散落着各种金属刑具和器皿，上面附着黑褐色的血污，让人不寒而栗。]],["enterfb203_ble"]=1,["id"]=[[fb220_12]],["item1"]=[[trigger01]],["item2"]=[[dgwp03c]],["name"]=[[祭厅]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb220_14"]={["dsc"]=[[这里是一间密闭的石室。石室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。石桌上放着不少书籍，可惜书页早已破败不堪。]],["enterfb203_ble"]=1,["id"]=[[fb220_14]],["item1"]=[[dgwp03c]],["name"]=[[密室]],["right"]=[[fb220_15]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb220_10]],["visible"]=0},["fb220_15"]={["dsc"]=[[这里是一个开阔的石洞，不知是天然形成的，还是人为开凿而成的。石洞顶上露出些许缝隙，阳光和空气透过缝隙传入石洞中。偶尔间出现一点响动，会激起石洞中的道道回音。]],["enterfb203